const agents={
 organiser:{name:'Organiser',letter:'O',desc:'Your people. Your plans. A little less organising.',placeholder:'Plan a ride, bring your people together…',welcome:'Tell me where you want to go and who you’d like to ride with. I can help prepare a plan and invitations for your known riders.',chips:['Invite my riding circle','Plan a weekend ride','Find my kind of ride']},
 curator:{name:'Curator',letter:'C',desc:'Considered objects for the way you live and ride.',placeholder:'Find the perfect gear, Italian objects or lifestyle robots…',welcome:'A little inspiration for the ride and the rest of your life. Tell me what you are looking for, or explore a collection with me.',chips:['Discover lifestyle robots','Explore Italian food & wine','Find Italian style']},
 mechanic:{name:'Mechanic',letter:'M',desc:'Understanding and care for your selected motorcycle.',placeholder:'Ask about your motorcycle, maintenance or charging…',welcome:'Describe a symptom or a maintenance question. I can prepare a checklist or a service note for the motorcycle selected in your Garage. This preview does not diagnose images or connect to live bike systems.',chips:['Prepare a pre-ride check','Help with a charging issue','Build a service note']},
 coach:{name:'Coach',letter:'C',desc:'Reflect on the ride. Make progress on the next one.',placeholder:'Review a ride, explore your telemetry, plan your practice…',welcome:'Select a ride or import your telemetry. I can help you prepare a debrief and a practice plan. Use coaching before or after riding, when you can give it your attention.',chips:['Review my selected ride','Plan a track session','Prepare for an adventure']}
};
const rememberedConversation=assistantPrefs.remember?read('conversation',[]):[];
const conversation=Array.isArray(rememberedConversation)?rememberedConversation.filter(m=>agents[m.agent]&&typeof m.text==='string'):[];
let pendingPhoto=null;
function persistConversation(){if(assistantPrefs.remember)write('conversation',conversation.map(({image,...m})=>m).slice(-100));else localStorage.removeItem('energica-conversation')}
const actionLabels={plan:'Create a ride plan',ride:'Open Ride Intelligence',community:'Explore community rides',service:'Download service note',outreach:'Review invitations',riders:'Add a known rider',collections:'Explore this collection'};
function renderChat(){
 const a=agents[state.agent],pageLabel={community:'Community',collections:'Collections',garage:'Garage',ride:'Ride Intelligence'}[state.page];
 $('#chat-name').textContent=a.name;$('#bar-role').textContent=a.name;$('#chat-emblem').textContent=a.letter;
 $('#chat-description').textContent=state.agent==='mechanic'?'Selected motorcycle · '+currentBike().model:a.desc;
 $('#assistant-context-label').textContent=pageLabel+' · One shared conversation';$('#chat-input').placeholder=a.placeholder;
 $('#messages').innerHTML=(conversation.length?'':`<div class="conversation-intro"><span class="eyebrow">YOUR ${a.name.toUpperCase()}</span><h3>${state.agent==='organiser'?'Where shall we go?':state.agent==='curator'?'A little inspiration.':state.agent==='mechanic'?'Let’s look after your ride.':'Every ride, a little wiser.'}</h3><p>${esc(a.welcome)}</p></div>`)+conversation.map(m=>`<div class="message ${m.role==='user'?'user':''}">${m.role==='assistant'?`<small>${agents[m.agent].name.toUpperCase()}${m.bike?' · '+esc(m.bike):''}</small>`:''}${m.image?`<img src="${m.image}" alt="Your attached photo">`:''}${esc(m.text)}${m.products?`<div class="chat-products">${m.products.map(id=>{const p=products.find(p=>p.id===id);return p?`<button data-chat-product="${p.id}">${productArt(p)}<span>${p.name}<small>${esc(productPrice(p))} · ${productKind(p)}</small></span><i data-lucide="arrow-up-right"></i></button>`:''}).join('')}</div>`:''}${actionLabels[m.action]?`<button class="secondary" data-chat-action="${m.action}"${m.category?` data-chat-category="${esc(m.category)}"`:''}>${actionLabels[m.action]} <i data-lucide="arrow-up-right"></i></button>`:''}</div>`).join('');
 $('#chat-chips').innerHTML=a.chips.map(c=>`<button>${c}</button>`).join('');
 $$('#chat-chips button').forEach(b=>b.onclick=()=>sendMessage(b.textContent));$$('[data-chat-product]').forEach(b=>b.onclick=()=>showProduct(b.dataset.chatProduct));
 $$('[data-chat-action]').forEach(b=>b.onclick=()=>{const action=b.dataset.chatAction;if(action==='plan')ridePlanner();else if(action==='ride'){closeAssistant(false);location.hash='ride'}else if(action==='community'){closeAssistant(false);location.hash='community'}else if(action==='outreach')reviewInvitations();else if(action==='riders')addRiderQuick();else if(action==='collections'){state.category=b.dataset.chatCategory||'All';renderProducts();closeAssistant(false);location.hash='collections'}else download(conversation.filter(m=>m.agent==='mechanic').map(m=>`${m.role.toUpperCase()}${m.bike?' · '+m.bike:''}: ${m.text}`).join('\n\n'),'energica-service-note.txt','text/plain')});
 $('#messages').scrollTop=$('#messages').scrollHeight;icons()
}
function openAssistant(prompt){$('#assistant-panel').hidden=false;$('#assistant-scrim').hidden=false;$('#assistant-expand').setAttribute('aria-expanded','true');$('#assistant-expand').setAttribute('aria-label','Collapse AI conversation');document.body.classList.add('conversation-open');renderChat();if(prompt)sendMessage(prompt);$('#chat-input').focus()}
function closeAssistant(focus=true){$('#assistant-panel').hidden=true;$('#assistant-scrim').hidden=true;$('#assistant-expand').setAttribute('aria-expanded','false');$('#assistant-expand').setAttribute('aria-label','Expand AI conversation');document.body.classList.remove('conversation-open');if(focus)$('#assistant-expand').focus()}
$('#assistant-expand').onclick=()=>$('#assistant-panel').hidden?openAssistant():closeAssistant();$('#assistant-close').onclick=()=>closeAssistant();$('#assistant-scrim').onclick=()=>closeAssistant();
$('#chat-input').addEventListener('focus',()=>{if($('#assistant-panel').hidden)openAssistant()});
$$('[data-assistant-prompt]').forEach(b=>b.onclick=()=>openAssistant(b.dataset.assistantPrompt));$('#garage-photo-help').onclick=()=>{openAssistant();$('#mechanic-photo').click()};
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&!modal.open&&!$('#assistant-panel').hidden)closeAssistant()});
function demoResponse(agent,input,hasImage){
 const q=input.toLowerCase();
 if(agent==='curator'){
  const category=/parmigiano|reggiano|cheese|food|wine|lambrusco|balsamic|vinegar|pantry|giusti/.test(q)?'Food & wine':/robot|lifestyle|cavallo|rover|unitree|g1|microduck|pollen|petoi|bittle|opencat|openexo|exoskeleton/.test(q)?'Robotics':/jacket|style|magliano|veja|sneaker|shoe/.test(q)?'Style':/coffee|espresso|italian|device|speaker|sound|bialetti|moka|lello|musso|lussino|gelato|ice cream/.test(q)?'Italian devices':/helmet|riding|protect/.test(q)?'Riding':/tour|adventure|bag|accessor|travel|warhol|sunglass|eyewear|retrosuperfuture/.test(q)?'Accessories':'All';
  const words=q.split(/[^a-z0-9]+/).filter(w=>w.length>2&&!['the','for','can','you','find','show','want','please','about','tell','what','with','your','that','this','like','some'].includes(w));
  const ranked=curatedProducts.map(p=>({p,score:words.filter(w=>(p.keywords+' '+p.name.toLowerCase()).includes(w)).length})).filter(x=>x.score>0).sort((a,b)=>b.score-a.score);
  const picks=ranked.length?ranked.slice(0,3).map(x=>x.p):products.filter(p=>category==='All'||p.category===category).slice(0,3);
  return{text:`A few considered ideas:\n\n${picks.map(p=>'• '+p.name+' — '+productPrice(p)).join('\n')}\n\nOpen an object for its details and maker link. You can save a selection here; prices, options and availability are confirmed by the maker. ${picks.some(p=>p.kind==='project')?'OpenExo is a research project.':''}`,products:picks.map(p=>p.id),action:'collections',category}

 }
 if(agent==='organiser'){
  if(/invit|reach out|contact|message|riding circle/.test(q)){
   if(!knownRiders.length)return{text:'Let’s start with the people you know. Scan a rider’s QR or add their phone number or email. I can then prepare a personal invitation for you to review.',action:'riders'};
   const mentioned=knownRiders.filter(r=>q.includes(r.name.toLowerCase()));outreachIds=mentioned.length?mentioned.map(r=>r.id):selectedRiders.size?[...selectedRiders]:knownRiders.map(r=>r.id);
   const people=knownRiders.filter(r=>outreachIds.includes(r.id));
   return{text:`I can prepare an invitation for ${people.map(r=>r.name).join(', ')}.\n\n${people.map(r=>'• '+r.name+' · '+r.pace+(r.location?' · '+r.location:'')).join('\n')}\n\nReview the draft, adjust the plan and choose email or WhatsApp for each rider. You send it from your own account; nothing is sent automatically.`,action:'outreach'}
  }
  if(/find|people|rider|like|pace/.test(q))return{text:`Your riding preferences: ${state.profile.pace||'Relaxed touring'}${state.profile.location?' around '+state.profile.location:''}.\nYour interests: ${state.interests.join(', ')||'not set yet'}.\n\n${knownRiders.length?'You have '+knownRiders.length+' known riders in your circle. Select the people you want to include and I can prepare invitations.':'Add people you already ride with, or browse the sample community rides to shape your next plan.'}`,action:knownRiders.length?'outreach':'community'};
  return{text:`Let’s make a day of it. Choose a meeting place, date and pace${state.profile.pace?' — your preference is '+state.profile.pace.toLowerCase():''}.\n\nI’ll prepare a local ride plan and a downloadable invitation. You can then invite people from your riding circle.`,action:'plan'}
 }
 return baseResponse(agent,input,hasImage)
}
function sendMessage(text){
 if(!text.trim())return;if($('#assistant-panel').hidden)openAssistant();
 const agent=state.agent,photo=pendingPhoto,bike=agent==='mechanic'?currentBike().model:null;
 conversation.push({role:'user',agent,text:text.trim(),image:photo,bike});pendingPhoto=null;$('#attachment-preview').hidden=true;$('#chat-input').value='';
 const answer=demoResponse(agent,text,!!photo);if(assistantPrefs.style==='Concise'&&agent==='organiser')answer.text=answer.text.split('\n\n').filter((_,i,a)=>i===0||i===a.length-1).join('\n\n');
 conversation.push({role:'assistant',agent,...answer,bike});persistConversation();renderChat()
}
$('#chat-form').onsubmit=e=>{e.preventDefault();sendMessage($('#chat-input').value||pendingPhoto&&'Please help me prepare a note for this photo.'||'')};
$('#mechanic-photo').onchange=e=>{const f=e.target.files[0];if(!f)return;if(f.size>10*1024*1024){toast('Choose a photo smaller than 10 MB.');return}if(!f.type.startsWith('image/')){toast('Please choose an image.');return}const fr=new FileReader();fr.onload=()=>{pendingPhoto=fr.result;openAssistant();$('#attachment-preview').hidden=false;$('#attachment-preview').innerHTML=`<img src="${fr.result}" alt="Attachment preview"><span>${esc(f.name)} · on this device</span><button type="button" id="remove-attachment" aria-label="Remove attachment">×</button>`;$('#remove-attachment').onclick=()=>{pendingPhoto=null;$('#attachment-preview').hidden=true}};fr.readAsDataURL(f);e.target.value=''};

function baseResponse(agent,input,hasImage){const q=input.toLowerCase();if(agent==='mechanic'){if(hasImage)return{text:'Your photo is attached to this conversation locally. This demo cannot inspect it.\n\nTell me the part, the symptom, when it began and whether a warning appears. If it involves brakes, tyres, steering, overheating or the high-voltage system, stop riding and arrange a qualified inspection. I can organise those details into a service note.',action:'service'};if(/charg|battery|power/.test(q))return{text:`Let’s document the charging issue on your ${currentBike().model}.\n\n1. Note the exact dashboard message and battery percentage.\n2. Record the charger location and connector type.\n3. Check the operator’s status and the vehicle manual.\n4. Stop if you notice heat, damage, smell or moisture.\n\nDo not open the battery or high-voltage components. Share the message and charging conditions with a qualified service partner.`,action:'service'};if(/service|note|problem|issue|warning/.test(q))return{text:'Here is a useful service-note structure:\n\nBike: '+currentBike().model+' ('+currentBike().year+')\nSymptom: '+input+'\nStarted: add date and circumstances\nWarning: copy the exact display text\nRepeatable: describe when it occurs\nPhotos: attach relevant views\n\nYou can download this conversation and add the missing details for your technician.',action:'service'};return{text:'A calm pre-ride routine for '+currentBike().model+':\n\n• Check tyre condition and pressures against the manual.\n• Check lights, mirrors and visible fluid leaks.\n• Confirm the controls and brakes feel normal while stationary.\n• Check charge, route and charging stops.\n• Check your protective equipment.\n\nA warning light or unfamiliar brake/steering feel needs a qualified inspection before you ride.',action:'service'}}if(agent==='coach'){if(/track/.test(q))return{text:'For a focused track session:\n\nChoose one skill with your instructor. Begin with a familiarisation session, then review consistency before adding pace. Compare repeatable sections of the circuit in your telemetry, and debrief between sessions.\n\nLean-angle peaks alone are not a measure of good riding. Context, line choice and an instructor’s observations matter.',action:'ride'};if(/adventure|trail/.test(q))return{text:'Start with the route and conditions: surface, weather, daylight, charging access and recovery options. Match the route to the least experienced rider.\n\nCarry communication and recovery essentials, agree meeting points and practise unfamiliar techniques with a qualified coach. Save the analysis for a stop, not while riding.',action:'plan'};const r=currentRide();return{text:`Your selected ride: ${r.name}${r.demo?' (sample data)':''}.\n\nDistance: ${r.distance.toFixed(1)} km\nRecorded duration: ${formatTime(r.duration)}\nAverage speed: ${Math.round(r.distance/r.duration*3600)} km/h\n\nUse the timeline to compare changes in speed with the route. A useful next session focuses on one skill and a repeatable section. Telemetry alone cannot establish safe or optimal technique.`,action:'ride'}}if(/find|people|rider|like/.test(q))return{text:`Your saved interests: ${state.interests.join(', ')||'not set yet'}.\n\nA good match starts with riding pace, experience, preferred distance and available dates. Browse the sample community rides or create a plan for your own group.\n\nNo profiles are matched or contacted automatically in this preview.`,action:'community'};if(/community|explore/.test(q))return{text:'Community has three sample ways to meet: a relaxed Dolomites tour, a social coffee ride and a track session. Save your interest or create a ride of your own.\n\nThese are illustrations, not bookable events.',action:'community'};return{text:'Let’s put a ride together. Choose a meeting place, date and pace. I’ll prepare a local plan and a downloadable invitation, ready for you to share with your friends.\n\nNo messages are sent without you.',action:'plan'}}

function sampleRide(id,name,region,distance,duration,phase){let points=[];for(let i=0;i<241;i++){const t=i/240;points.push({t:t*duration,lat:46.49+.06*t+.009*Math.sin(t*17+phase),lon:11.75+.1*t+.015*Math.sin(t*20),speed:Math.max(0,Math.round(48+20*Math.sin(t*21+phase)+9*Math.sin(t*67)))*(i<2||i>238?.2:1),lean:Math.round(19*Math.sin(t*21)+9*Math.sin(t*51)),battery:Math.round(95-t*(id==='dolomites'?34:22)),elevation:1250+430*Math.sin(t*3.1)})}return{id,name,region,distance,duration,points,demo:true,hasTime:true,date:'SAMPLE JOURNEY',bike:'Energica Experia'}}
let rides=[sampleRide('dolomites','The Dolomites loop','SOUTH TYROL, ITALY',86.4,4920,.7),sampleRide('modena','A morning in Modena','EMILIA-ROMAGNA, ITALY',42.8,2940,2),sampleRide('coast','Along the coast','LIGURIA, ITALY',67.2,4200,4),...read('rides',[])];let selectedRide=0;let videoUrl=null;let videoOffset=0;
function currentRide(){return rides[selectedRide]||rides[0]}
function formatTime(t){t=Math.max(0,Math.floor(t||0));return t>=3600?Math.floor(t/3600)+':'+String(Math.floor(t%3600/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0'):String(Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0')}
function renderRides(){$('#ride-count').textContent=rides.length;$('#ride-list').innerHTML=rides.map((r,i)=>`<button class="ride-choice ${i===selectedRide?'active':''}" data-ride="${i}"><span>${r.demo?'SAMPLE RIDE':'IMPORTED ON THIS DEVICE'}</span><h3>${esc(r.name)}</h3><small>${r.distance.toFixed(1)} km · ${formatTime(r.duration)}</small></button>`).join('');$$('[data-ride]').forEach(b=>b.onclick=()=>{selectedRide=Number(b.dataset.ride);state.progress=0;pauseRide();removeVideo();renderRides();renderRideDetail()});}
function renderRideDetail(){const r=currentRide();$('#ride-region').textContent=r.region;$('#ride-name').textContent=r.name;$('#ride-meta').textContent=r.bike+' · '+(r.demo?'Illustrative route and telemetry':r.hasTime?'Imported route and timestamps':'Route imported · timing estimated');$('#ride-status').textContent=r.demo?'SAMPLE RIDE':'YOUR DATA';let bat=r.points.filter(p=>Number.isFinite(p.battery));let used=bat.length>1?Math.max(0,bat[0].battery-bat.at(-1).battery):null;$('#ride-stats').innerHTML=[['DISTANCE',r.distance.toFixed(1),'km'],['DURATION',formatTime(r.duration),''],['AVG. SPEED',Math.round(r.distance/(r.duration/3600)),'km/h'],['BATTERY USED',used??'—',used===null?'':'%']].map(a=>`<div class="stat"><small>${a[0]}</small><b>${a[1]}<span>${a[2]}</span></b></div>`).join('');$('#route-distance').textContent=r.distance.toFixed(1)+' km';$('#play-duration').textContent=formatTime(r.duration);$('#ride-insight-text').textContent=r.demo?'Explore sample telemetry, then build a practice plan with your Coach.':'Your imported data is ready for a closer look with your Coach.';drawRoad();icons()}
function canvasSetup(el){const r=el.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);if(!r.width)return null;el.width=Math.round(r.width*d);el.height=Math.round(r.height*d);const ctx=el.getContext('2d');ctx.scale(d,d);return{ctx,w:r.width,h:r.height}}
function routeScreen(points,w,h){let lats=points.map(p=>p.lat),lons=points.map(p=>p.lon),minLat=Math.min(...lats),maxLat=Math.max(...lats),minLon=Math.min(...lons),maxLon=Math.max(...lons),xScale=Math.max((maxLon-minLon)*Math.cos((minLat+maxLat)/2*Math.PI/180),.00001),yScale=Math.max(maxLat-minLat,.00001),scale=Math.min((w-90)/xScale,(h-80)/yScale);return points.map(p=>[w/2+(p.lon-(minLon+maxLon)/2)*Math.cos((minLat+maxLat)/2*Math.PI/180)*scale,h/2-(p.lat-(minLat+maxLat)/2)*scale])}
function drawMap(){const setup=canvasSetup($('#route-canvas'));if(!setup)return;const{ctx,w,h}=setup,r=currentRide();ctx.fillStyle='#1b2814';ctx.fillRect(0,0,w,h);for(let k=0;k<16;k++){ctx.strokeStyle=k%3===0?'#3a4e2c':'#2b3d20';ctx.lineWidth=.7;ctx.beginPath();for(let x=-30;x<w+40;x+=4){const y=k*22-45+Math.sin(x*.015+k*.25)*25+Math.sin(x*.03-k)*8;x===-30?ctx.moveTo(x,y):ctx.lineTo(x,y)}ctx.stroke()}let pts=routeScreen(r.points,w,h);ctx.lineCap='round';function path(color,width,end=pts.length){ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();pts.slice(0,end).forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.stroke()}path('#435935',8);path('#91ad75',3);const index=Math.round(state.progress*(pts.length-1));path('#78be20',3,index+1);for(const[k,p]of [[0,pts[0]],[1,pts.at(-1)]]){ctx.fillStyle=k?'#adc78f':'#78be20';ctx.beginPath();ctx.arc(...p,5,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#d6e9be';ctx.lineWidth=2;ctx.stroke()}const p=pts[index];ctx.fillStyle='#78be2044';ctx.beginPath();ctx.arc(...p,13,0,Math.PI*2);ctx.fill();ctx.fillStyle='#a8e35b';ctx.beginPath();ctx.arc(...p,5,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#e5f3d6';ctx.lineWidth=2;ctx.stroke()}
function pointAt(){const r=currentRide(),t=state.progress*r.duration;let i=r.points.findIndex(p=>p.t>=t);return r.points[i<0?r.points.length-1:i]}
function drawTelemetry(){const setup=canvasSetup($('#telemetry-canvas'));if(!setup)return;const {ctx,w,h}=setup,r=currentRide(),key=state.metric,vals=r.points.map(p=>p[key]),available=vals.some(Number.isFinite);ctx.clearRect(0,0,w,h);for(let i=1;i<4;i++){ctx.strokeStyle='#334927';ctx.lineWidth=.7;ctx.beginPath();ctx.moveTo(0,i*h/4);ctx.lineTo(w,i*h/4);ctx.stroke()}if(!available){ctx.fillStyle='#a1bd88';ctx.font='11px Arial';ctx.textAlign='center';ctx.fillText('This ride has no '+key+' data.',w/2,h/2);$('#metric-readout').textContent='Not recorded';return}const valid=vals.filter(Number.isFinite),min=key==='lean'?Math.min(-35,...valid):0,max=key==='battery'?100:Math.max(key==='lean'?35:40,...valid)*1.1;const xy=(p)=>[p.t/r.duration*w,h-14-(p[key]-min)/(max-min)*(h-28)];ctx.beginPath();let first=true;r.points.forEach(p=>{if(!Number.isFinite(p[key]))return;let [x,y]=xy(p);first?ctx.moveTo(x,y):ctx.lineTo(x,y);first=false});ctx.strokeStyle='#78be20';ctx.lineWidth=1.6;ctx.stroke();ctx.lineTo(w,h);ctx.lineTo(0,h);ctx.closePath();let grad=ctx.createLinearGradient(0,0,0,h);grad.addColorStop(0,'#78be2040');grad.addColorStop(1,'#78be2003');ctx.fillStyle=grad;ctx.fill();const x=state.progress*w;ctx.strokeStyle='#acd477';ctx.lineWidth=1;ctx.setLineDash([3,3]);ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,h);ctx.stroke();ctx.setLineDash([]);const p=pointAt();$('#metric-readout').textContent=Number.isFinite(p[key])?Math.round(p[key])+(key==='speed'?' km/h':key==='lean'?'°':'%'):'Not recorded'}
function updatePlayback(){$('#ride-scrubber').value=Math.round(state.progress*1000);$('#play-time').textContent=formatTime(currentRide().duration*state.progress);$('#dash-time').textContent=formatTime($('#dash-video').hidden?currentRide().duration*state.progress:$('#dash-video').currentTime);}
function drawRoad(){if(state.page!=='ride')return;drawMap();drawTelemetry();updatePlayback()}
function pauseRide(){state.playing=false;$('#play-ride').innerHTML='<i data-lucide="play"></i>';$('#play-ride').setAttribute('aria-label','Play ride');$('#dash-video').pause();icons()}
$('#play-ride').onclick=async()=>{if(state.playing){pauseRide();return}if(state.progress>=1)state.progress=0;state.playing=true;$('#play-ride').innerHTML='<i data-lucide="pause"></i>';$('#play-ride').setAttribute('aria-label','Pause ride');if(videoUrl){const v=$('#dash-video');v.playbackRate=Math.min(4,Number($('#play-speed').value));v.currentTime=Math.max(0,Math.min(v.duration||0,state.progress*currentRide().duration-videoOffset));try{await v.play()}catch{pauseRide();toast('This video cannot be played. Try an MP4 or WebM recording.')}}icons()};
function seek(progress){state.progress=Math.max(0,Math.min(1,progress));if(videoUrl){const v=$('#dash-video');if(Number.isFinite(v.duration))v.currentTime=Math.max(0,Math.min(v.duration,state.progress*currentRide().duration-videoOffset))}drawRoad()}
$('#ride-scrubber').oninput=e=>seek(Number(e.target.value)/1000);$('#telemetry-canvas').onclick=e=>{const r=e.target.getBoundingClientRect();seek((e.clientX-r.left)/r.width)};
$$('[data-metric]').forEach(b=>b.onclick=()=>{state.metric=b.dataset.metric;$$('[data-metric]').forEach(x=>x.classList.toggle('active',x===b));drawTelemetry()});
let lastFrame=0,lastDraw=0;function tick(t){const elapsed=Math.min(.15,(t-lastFrame)/1000);lastFrame=t;if(state.playing){state.progress=videoUrl?Math.min(1,Math.max(0,($('#dash-video').currentTime+videoOffset)/currentRide().duration)):Math.min(1,state.progress+elapsed*Number($('#play-speed').value)/currentRide().duration);if(t-lastDraw>50){drawRoad();lastDraw=t}if(state.progress>=1)pauseRide()}requestAnimationFrame(tick)}requestAnimationFrame(tick);document.addEventListener('visibilitychange',()=>{if(document.hidden)pauseRide()});
$('#play-speed').onchange=()=>{if(videoUrl)$('#dash-video').playbackRate=Math.min(4,Number($('#play-speed').value))};
$('#video-import').onchange=e=>{const f=e.target.files[0];if(!f)return;if(!f.type.startsWith('video/')){toast('Choose a video recording.');return}removeVideo();videoUrl=URL.createObjectURL(f);const v=$('#dash-video');v.src=videoUrl;v.hidden=false;$('#dash-empty').hidden=true;$('#video-settings').hidden=false;v.onloadedmetadata=()=>{seek(state.progress);toast('Video added locally. Adjust the ride offset to synchronise.')};v.onerror=()=>{toast('This video format is not supported by your browser.');removeVideo()};v.onended=pauseRide;e.target.value=''};
function removeVideo(){pauseRide();const v=$('#dash-video');v.removeAttribute('src');v.load();v.hidden=true;$('#dash-empty').hidden=false;$('#video-settings').hidden=true;if(videoUrl)URL.revokeObjectURL(videoUrl);videoUrl=null;videoOffset=0;$('#video-offset').value=0}
$('#remove-video').onclick=removeVideo;$('#video-offset').onchange=e=>{videoOffset=Number(e.target.value)||0;seek(state.progress)};
const haversine=(a,b)=>{const rad=Math.PI/180,dlat=(b.lat-a.lat)*rad,dlon=(b.lon-a.lon)*rad,v=Math.sin(dlat/2)**2+Math.cos(a.lat*rad)*Math.cos(b.lat*rad)*Math.sin(dlon/2)**2;return 6371*2*Math.atan2(Math.sqrt(v),Math.sqrt(Math.max(0,1-v)))};
function importPoints(raw,name){if(!Array.isArray(raw)||raw.length<2||raw.length>20000)throw Error('Choose a ride with 2–20,000 route points.');let points=raw.map((p,i)=>{const lat=Number(p.lat??p.latitude),lon=Number(p.lon??p.lng??p.longitude);if(!Number.isFinite(lat)||!Number.isFinite(lon)||Math.abs(lat)>90||Math.abs(lon)>180)throw Error('Every point needs a valid latitude and longitude.');const has=n=>n!==null&&n!==''&&n!==undefined&&Number.isFinite(Number(n));let time=p.t??p.time??p.timestamp;let t=typeof time==='string'&&!Number.isFinite(Number(time))?Date.parse(time)/1000:has(time)?Number(time):null;return{lat,lon,t,speed:has(p.speed)?Math.max(0,Number(p.speed)):null,lean:has(p.lean)?Number(p.lean):null,battery:has(p.battery)?Math.max(0,Math.min(100,Number(p.battery))):null,elevation:has(p.elevation??p.ele)?Number(p.elevation??p.ele):null}});let hasTime=points.every(p=>Number.isFinite(p.t));if(hasTime){const start=points[0].t;points.forEach(p=>p.t-=start);if(points.some((p,i)=>i&&p.t<=points[i-1].t))throw Error('Ride timestamps must increase in order.');}else points.forEach((p,i)=>p.t=i*5);let distance=0;points.forEach((p,i)=>{if(i){let d=haversine(points[i-1],p);distance+=d;if(p.speed===null)p.speed=d/(p.t-points[i-1].t)*3600}else if(p.speed===null)p.speed=0});return{id:'import-'+Date.now(),name:name.slice(0,80),region:'YOUR IMPORTED JOURNEY',distance,duration:points.at(-1).t,points,demo:false,hasTime,bike:currentBike().model}}
$('#ride-import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>10*1024*1024)throw Error('Choose a ride file smaller than 10 MB.');const text=await file.text();let raw,name=file.name.replace(/\.(gpx|json)$/i,'');if(file.name.toLowerCase().endsWith('.gpx')){const xml=new DOMParser().parseFromString(text,'application/xml');if(xml.querySelector('parsererror'))throw Error('This GPX file could not be read.');const pts=[...xml.getElementsByTagName('trkpt')];if(!pts.length)pts.push(...xml.getElementsByTagName('rtept'));raw=pts.map(p=>({lat:p.getAttribute('lat'),lon:p.getAttribute('lon'),time:p.getElementsByTagName('time')[0]?.textContent,ele:p.getElementsByTagName('ele')[0]?.textContent}));name=xml.getElementsByTagName('name')[0]?.textContent||name}else{const obj=JSON.parse(text);raw=Array.isArray(obj)?obj:obj.points;name=typeof obj.name==='string'?obj.name:name}const ride=importPoints(raw,name);rides.push(ride);selectedRide=rides.length-1;state.progress=0;removeVideo();if(state.privacy.local)write('rides',rides.filter(r=>!r.demo));renderRides();renderRideDetail();toast('Ride imported. Your file stays on this device.')}catch(err){toast(err.message||'Could not import this ride.')}finally{e.target.value=''}};
function download(text,name,type){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('#export-ride').onclick=()=>{const r=currentRide();const header='elapsed_seconds,latitude,longitude,speed_kmh,lean_degrees,battery_percent,elevation_m';const csv=[header,...r.points.map(p=>[p.t,p.lat,p.lon,p.speed,p.lean??'',p.battery??'',p.elevation??''].join(','))].join('\n');download(csv,'energica-'+r.id+'.csv','text/csv');toast('Ride telemetry exported.')};
$('#review-with-coach').onclick=()=>openAssistant('Review my selected ride');
$('#privacy-button').onclick=()=>{openModal(`<span class="eyebrow">RIDE INTELLIGENCE</span><h2>It is your data.</h2><p class="modal-intro">This prototype processes ride files and videos in your browser. Nothing is sent to Energica, other riders or data partners. The controls below save your preferences locally.</p><label class="toggle-row"><div>Remember imported rides<small>Store route and telemetry data in this browser.</small></div><input type="checkbox" id="privacy-local" ${state.privacy.local?'checked':''}></label><label class="toggle-row"><div>Allow community introductions<small>Preference only; no profile is shared in this preview.</small></div><input type="checkbox" id="privacy-community" ${state.privacy.community?'checked':''}></label><label class="toggle-row"><div>Contribute aggregated road insights<small>Off by default. No data sharing is implemented in this preview.</small></div><input type="checkbox" id="privacy-analytics" ${state.privacy.analytics?'checked':''}></label><div class="form-actions"><button class="secondary" id="delete-rides">Delete imported rides</button><button class="primary" id="save-privacy">Save preferences</button></div>`);$('#save-privacy').onclick=()=>{state.privacy={local:$('#privacy-local').checked,community:$('#privacy-community').checked,analytics:$('#privacy-analytics').checked};write('privacy',state.privacy);if(state.privacy.local)write('rides',rides.filter(r=>!r.demo));else localStorage.removeItem('energica-rides');closeModal();toast('Privacy preferences saved.')};$('#delete-rides').onclick=()=>{rides=rides.filter(r=>r.demo);selectedRide=0;state.progress=0;localStorage.removeItem('energica-rides');removeVideo();renderRides();renderRideDetail();closeModal();toast('Imported rides deleted from this browser.')}};
$('#about-preview').onclick=()=>openModal(`<span class="eyebrow">ENERGICA · PEOPLE & PASSION</span><h2>Four places. One conversation.</h2><p class="modal-intro">Bring your people together in Community, discover remarkable objects in Collections, care for every motorcycle in Garage and explore your journeys in Ride Intelligence.</p><h3>Your Organiser, Curator, Mechanic and Coach.</h3><p class="modal-intro">Use the expanding chat bar at the top of every page. Your conversation stays with you as the role changes. Turn on local conversation memory in profile settings to keep text history between visits.</p><p class="modal-intro">This prototype uses demo responses. The collection mixes real maker selections and labelled Energica concepts. Maker prices are dated references; example riders are illustrative. No live AI model, vehicle diagnostics, account service or payment provider is connected. Invitations open your own email or WhatsApp for review and sending.</p><p class="local-note">The Energica logo and green come from the supplied brand materials. Files, rider contacts, motorcycle records and preferences stay in this browser.</p>`);
window.addEventListener('resize',drawRoad);
